/**
 * Read a component's public surface from its committed type declarations.
 *
 * `packages/web-components/src/components.d.ts` is generated by Stencil and
 * committed, so it is the one place the props — with their types, defaults, and
 * doc comments — exist without a build step. Two generators need it (the
 * registry entries and `llms-full.txt`), so the parse lives here rather than
 * twice, where the two copies would eventually disagree.
 *
 * One detail the parse must handle, because it silently produced an empty
 * result the first time it was written: Stencil emits each component **twice**,
 * as the class interface and again inside `JSX.IntrinsicElements`. The two are
 * not identical — the JSX interface carries the form-associated `form` and
 * `name` members the class interface omits. A last-wins parse drops every prop;
 * a first-only parse drops the form members. The two are merged here, keeping
 * prose from whichever has it, so a prop that appears in either is reported
 * once.
 */
import { readFileSync } from "node:fs"

const pascal = (name) =>
  name
    .split("-")
    .map((w) => w[0].toUpperCase() + w.slice(1))
    .join("")

/**
 * @param {string} typesFilePath Absolute path to `components.d.ts`.
 * @returns {Map<string, Array<{name: string, type: string, default: string|null, description: string}>>}
 *   Keyed by interface name (`SkButton`), not by tag or registry name.
 */
export function readComponentTypes(typesFilePath) {
  const source = readFileSync(typesFilePath, "utf8")
  const byInterface = new Map()

  const interfaceRe = /interface\s+(Sk\w+)\s*\{([\s\S]*?)\n\s*\}/g
  for (const match of source.matchAll(interfaceRe)) {
    const [, name, body] = match
    const existing = byInterface.get(name) ?? new Map()
    const propRe = /\/\*\*([\s\S]*?)\*\/\s*"([^"]+)"(\??):\s*([^;]+);|"([^"]+)"(\??):\s*([^;]+);/g
    for (const prop of body.matchAll(propRe)) {
      const doc = prop[1] ?? ""
      const propName = prop[2] ?? prop[5]
      const type = (prop[4] ?? prop[7]).trim().replace(/\s+/g, " ")
      const defaultMatch = doc.match(/@default\s+(.+)/)
      const description = doc
        .split("\n")
        .map((line) => line.replace(/^\s*\*?\s?/, "").trim())
        .filter((line) => line && !line.startsWith("@default"))
        .join(" ")
        .trim()
      const previous = existing.get(propName)
      existing.set(propName, {
        name: propName,
        type,
        default: defaultMatch ? defaultMatch[1].trim() : (previous?.default ?? null),
        // Prefer the entry that has prose; a doc-less duplicate must not erase it.
        description: description || previous?.description || "",
      })
    }
    byInterface.set(name, existing)
  }

  return new Map([...byInterface].map(([name, props]) => [name, [...props.values()]]))
}

/** The props for one registry entry (`icon-button` → `SkIconButton`). */
export function propsFor(types, registryName) {
  return types.get(`Sk${pascal(registryName)}`) ?? []
}

/**
 * The custom events a component dispatches, read from its source.
 *
 * Two forms appear in the codebase and both must be seen:
 *
 *   - a literal:  `new CustomEvent("sk-tab-change", …)`
 *   - via a shared emitter: `emitOpenChange(state, open)`, which dispatches
 *     `new CustomEvent(DIALOG_EVENT, …)` where `DIALOG_EVENT` is
 *     `"sk-open-change"`.
 *
 * A component is credited with an event only when its own source dispatches it
 * or calls the emitter that does — so `sk-tooltip`, which imports the dialog
 * *state* type but emits nothing, correctly reports none.
 *
 * @param {string} componentSource Source text of `sk-<name>.tsx`.
 * @param {{constants: Record<string,string>, emitters: Record<string,{kind:string,event?:string,constant?:string}>}} events
 *   From {@link readEventMetadata}.
 */
export function eventsFor(componentSource, events) {
  const names = new Set()

  for (const match of componentSource.matchAll(/new CustomEvent\(\s*"([^"]+)"/g)) {
    names.add(match[1])
  }
  for (const [fnName, emitter] of Object.entries(events.emitters)) {
    if (!new RegExp(`\\b${fnName}\\s*\\(`).test(componentSource)) continue
    if (emitter.kind === "literal") names.add(emitter.event)
    else {
      const value = events.constants[emitter.constant]
      if (value) names.add(value)
    }
  }

  return [...names].sort()
}

/**
 * Event-name constants and the shared functions that dispatch them, discovered
 * from the shared base sources rather than hardcoded, so renaming a constant in
 * a base is reflected here without an edit.
 *
 * The link is read from each exported function's own body: if it constructs a
 * `CustomEvent`, the component that calls that function emits that event. This
 * is what catches `sk-value-change`, which no component dispatches itself —
 * `setupFormControl()` in `form-control-base.ts` does, and Input, Textarea, and
 * Select all call it. A hardcoded list would have missed them the moment a base
 * changed.
 *
 * Only *exported* functions are considered: an inner helper is not something a
 * component can call.
 */
export function readEventMetadata(sharedDir) {
  const constants = {}
  const emitters = {}

  for (const file of ["dialog-base.ts", "form-control-base.ts"]) {
    let source
    try {
      source = readFileSync(`${sharedDir}/${file}`, "utf8")
    } catch {
      continue
    }
    for (const match of source.matchAll(/export const ([A-Z_]+)\s*=\s*"([^"]+)"/g)) {
      constants[match[1]] = match[2]
    }
    // `export function setupFormControl(...) { … new CustomEvent("sk-value-change", …) }`
    const fnRe = /export function (\w+)\s*\([^)]*\)[^{]*\{([\s\S]*?)\n\}/g
    for (const match of source.matchAll(fnRe)) {
      const [, fnName, body] = match
      const literal = body.match(/new CustomEvent\(\s*"([^"]+)"/)
      if (literal) {
        emitters[fnName] = { kind: "literal", event: literal[1] }
        continue
      }
      const viaConstant = body.match(/new CustomEvent\(\s*([A-Z_]+)\b/)
      if (viaConstant) emitters[fnName] = { kind: "constant", constant: viaConstant[1] }
    }
  }

  return { constants, emitters }
}
